const express = require('express');
const { v4: uuidv4 } = require('uuid');

class RESTAPI {
    constructor(port = 3000) {
        this.port = port;
        this.app = express();
        this.items = new Map();
        this.app.use(express.json());
        this.setupRoutes();
    }

    setupRoutes() {
        this.app.get('/api/items', (req, res) => {
            const items = Array.from(this.items.values());
            res.json({ success: true, data: items });
        });

        this.app.post('/api/items', (req, res) => {
            const id = uuidv4();
            const item = { id, ...req.body, createdAt: new Date().toISOString() };
            this.items.set(id, item);
            res.status(201).json({ success: true, data: item });
        });
    }

    start() {
        this.app.listen(this.port, () => {
            console.log(`服务器运行在 http://localhost:${this.port}`);
        });
    }
}

function useForm(initialValues, validate) {
  const [values, setValues] = useState(initialValues);
  const [errors, setErrors] = useState({});
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setValues(prev => ({ ...prev, [name]: value }));
    if (errors[name]) setErrors(prev => ({ ...prev, [name]: '' }));
  };

  const handleSubmit = async (onSubmit) => {
    setIsSubmitting(true);
    const validationErrors = validate(values);
    if (Object.keys(validationErrors).length === 0) {
      await onSubmit(values);
    } else {
      setErrors(validationErrors);
    }
    setIsSubmitting(false);
  };

  const reset = () => {
    setValues(initialValues);
    setErrors({});
    setIsSubmitting(false);
  };

  return { values, errors, isSubmitting, handleChange, handleSubmit, reset };
}

function useApiCall(apiFunction) {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const execute = useCallback(async (...args) => {
    setLoading(true);
    setError(null);
    try {
      const result = await apiFunction(...args);
      setData(result);
      return result;
    } catch (err) {
      setError(err.message || 'Request failed');
      throw err;
    } finally {
      setLoading(false);
    }
  }, [apiFunction]);

  return { data, loading, error, execute };
}

class DataCleaningPipeline:
    def __init__(self):
        self.steps = []

    def add_step(self, name, func):
        self.steps.append((name, func))
        return self

    def execute(self, data):
        result = data.copy()
        for name, func in self.steps:
            try:
                result = func(result)
            except Exception as e:
                print(f"Failed at {name}: {str(e)}")
                raise
        return result

