  }
);

import { jest } from '@jest/globals';

export function createMockModule(modulePath, mocks = {}) {
  const mockModule = {};
  const moduleExports = require(modulePath);

  for (const [key, value] of Object.entries(moduleExports)) {
    if (typeof value === 'function') {
      mockModule[key] = jest.fn().mockImplementation((...args) => {
        if (mocks[key]) return mocks[key](...args);
        return Promise.resolve(null);
      });
    }
  }

  jest.doMock(modulePath, () => mockModule);
  return mockModule;
}

export async function waitFor(condition, timeout = 5000) {
  const start = Date.now();
  while (Date.now() - start < timeout) {
    if (await condition()) return true;
    await new Promise(resolve => setTimeout(resolve, 100));
  }
  throw new Error('Timeout');
}

