class PasswordHasher:
    def __init__(self, rounds=12):
        self.rounds = rounds

    def hash(self, password):
        salt = bcrypt.gensalt(rounds=self.rounds)
        return bcrypt.hashpw(password.encode('utf-8'), salt).decode('utf-8')

    def verify(self, password, hashed):
        return bcrypt.checkpw(password.encode('utf-8'), hashed.encode('utf-8'))

    def generate_reset_token(self):
        return secrets.token_urlsafe(32)

import time
import functools
import logging

def profile(func=None, *, threshold=1.0):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            start = time.perf_counter()
            result = func(*args, **kwargs)
            elapsed = time.perf_counter() - start
            if elapsed > threshold:
                logging.warning(f"Slow: {func.__name__} took {elapsed:.3f}s")
            return result
        return wrapper
    if func: return decorator(func)
    return decorator

export const dateUtils = {
  format(date, fmt = 'YYYY-MM-DD') {
    const d = new Date(date);
    const year = d.getFullYear();
    const month = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    return fmt.replace('YYYY', year).replace('MM', month).replace('DD', day);
  },

  addDays(date, days) {
    const result = new Date(date);
    result.setDate(result.getDate() + days);
    return result;
  },

  diffDays(date1, date2) {
    const msPerDay = 24 * 60 * 60 * 1000;
    return Math.floor(Math.abs(date1 - date2) / msPerDay);
  }
};

